import { Divider, Form, Modal, Radio, Select } from "antd";
import carApi from "api/carApi";
import { addToken } from "components/store/tokenSlice";
import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";

export default function EditProductStatus({ open, data, onClose, onSubmit }) {
  const user = useSelector((state) => state.token);
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const [form] = Form.useForm();
  const [result, setResult] = useState({});
  const [users, setUsers] = useState([]);
  const [defaultUser, setDefaultUser] = useState({});
  const [disabled, setDisabled] = useState(false);
  useEffect(() => {
    // console.log(data);
    setResult(data);
    fetchAllUser();
    if (data.status_type_id === 2 || data.status_type_id === 3) {
      setDisabled(false);
    } else {
      setDisabled(true);
    }

    return () => {
      setUsers([]);
      setResult({});
      setDefaultUser({});
      setDisabled(false);
    };
  }, [data]);

  const fetchAllUser = async () => {
    await carApi
      .get("/salecar/admin/users", {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        const data = response.data;
        setUsers(data);
      })
      .catch((error) => {
        // setLoading(false);
        dispatch(addToken({}));
        navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "กรุณาเข้าสู่ระบบ",
          centered: true,
        });
      });
  };
  const handleClose = () => {
    onClose(false);
  };

  const handleChange = (e) => {
    if (e.target.value === 1) setDisabled(true);
    else setDisabled(false);
    setResult({ ...result, status_type_id: e.target.value });
  };

  const handleSelect = (e) => {
    console.log("handleSelect", e.label);
    setResult({ ...result, process_by_user_id: e.label });
  };

  const handleSubmit = () => {
    onSubmit(result);
    onClose(false);
  };

  const checkCurrentUser = () => {
    const current = users.find((user) => user.id === data.user_id);
    setDefaultUser(current);
  };

  useEffect(() => {
    checkCurrentUser();
  }, [users]);

  if (data && open && defaultUser) {
    return (
      <Modal
        title={
          "สถานะสินค้า : " +
          result.brand +
          "  " +
          result.model +
          "  " +
          result.year
        }
        open={open}
        onOk={handleSubmit}
        onCancel={handleClose}
      >
        <Divider />
        <Radio.Group
          direction="vertical"
          style={{ width: 500 }}
          defaultValue={data.status_type_id}
          onChange={handleChange}
        >
          <Radio style={{ width: "100%" }} value={1}>
            คงอยู่
          </Radio>
          <Radio style={{ width: "100%" }} value={2}>
            รอดำเนินการ (อยู่ระหว่างซื้อขาย)
          </Radio>
          <Radio style={{ width: "100%" }} value={3}>
            ขายแล้ว
          </Radio>
          <Form
            disabled={disabled}
            form={form}
            name="basic"
            labelCol={{
              span: 4,
            }}
            wrapperCol={{
              span: 18,
            }}
            autoComplete="off"
          >
            <Form.Item
              label="กับผู้ใช้"
              name="date"
              rules={[
                {
                  required: true,
                  message: "กำหนดวันที่สิ้นสุด",
                },
              ]}
            >
              <Select
                onChange={(v, e) => handleSelect(e)}
                //   disabled={value === 1 ? false : true}
                defaultValue={defaultUser.car_tent_name}
              >
                {users.map((user) => {
                  return (
                    <Select.Option
                      key={user.id}
                      value={
                        user.car_tent_name
                          ? user.car_tent_name
                          : user.firstname +
                            " " +
                            user.lastname +
                            " (" +
                            user.nickname +
                            ")"
                      }
                      label={user.id}
                    />
                  );
                })}
              </Select>
            </Form.Item>
          </Form>
        </Radio.Group>
      </Modal>
    );
  }
}
