import React, { useState, useEffect } from "react";

import carApi from "api/carApi";
import {
  Button,
  Image,
  Modal,
  Space,
  Table,
  Tag,
  Tooltip,
  Typography,
} from "antd";
// import { useMediaQuery } from "@mui/material";
import { currencyFormat } from "components/utils/Utils";
import Loading from "components/Loading";

import moment from "moment/moment";
import "moment/locale/th";
import { Link, useNavigate } from "react-router-dom";
import AuctionUserListModal from "./AuctionUserListModal";
import { EditOutlined } from "@mui/icons-material";
import EditProductStatus from "./EditProductStatus";
import { useDispatch, useSelector } from "react-redux";
import { addToken } from "components/store/tokenSlice";
import ReactPDF, {
  Page,
  Text,
  View,
  Document,
  StyleSheet,
  PDFViewer,
} from "@react-pdf/renderer";

import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
import { offerPricePDF } from "./OfferPricePDF";

pdfMake.fonts = {
  THSarabunNew: {
    normal: "THSarabunNew.ttf",
    bold: "THSarabunNew Bold.ttf",
    italics: "THSarabunNew Italic.ttf",
    bolditalics: "THSarabunNew BoldItalic.ttf",
  },
  AngsanaNew: {
    normal: "AngsanaNew.ttf",
    bold: "AngsanaNew Bold.ttf",
    italics: "AngsanaNew Italic.ttf",
    bolditalics: "AngsanaNew Bold Italic.ttf",
  },
  Roboto: {
    normal: "Roboto-Regular.ttf",
    bold: "Roboto-Medium.ttf",
    italics: "Roboto-Italic.ttf",
    bolditalics: "Roboto-MediumItalic.ttf",
  },
};

pdfMake.vfs = pdfFonts.pdfMake.vfs;

const styles = StyleSheet.create({
  page: {
    flexDirection: "row",
    backgroundColor: "#E4E4E4",
  },
  section: {
    margin: 10,
    padding: 10,
    flexGrow: 1,
  },
});

const MyDocument = () => (
  <Document>
    <Page size="A4" style={styles.page}>
      <View style={styles.section}>
        <Text>Section #1</Text>
      </View>
      <View style={styles.section}>
        <Text>Section #2</Text>
      </View>
    </Page>
  </Document>
);

export default function BookProductList() {
  const user = useSelector((state) => state.token);
  const navigate = useNavigate();
  const dispatch = useDispatch();
  // const theme = useTheme();
  // const isMediumUp = useMediaQuery(theme.breakpoints.up("md"));
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState();
  const [auctionUserList, setAuctionUserList] = useState([]);
  const [dataEdit, setDataEdit] = useState({});
  const [openAuctionListModal, setOpenAuctionListModal] = useState(false);
  const [openProductStatusModal, setOpenProductStatusModal] = useState(false);

  useEffect(() => {
    pdfMake.vfs = pdfFonts.pdfMake.vfs;
  }, []);

  const columns = [
    // isMediumUp
    {
      key: 1,
      // dataIndex: "image_path",
      title: "รูปภาพ",
      render: (rec) => {
        return (
          <Space direction="vertical" align="center">
            <Image width={200} src={rec.image_path} />
            <Typography>เลขสัญญาเดิม : {rec.contract_no}</Typography>
            <Typography>เลขสัญญาเดิม : {rec.register_no}</Typography>
          </Space>
        );
      },
    },
    // : {
    //     key: 0,
    //   },

    {
      key: 2,
      // dataIndex: "user_id",
      title: "รายละเอียดรถ",
      render: (rec) => {
        return (
          <div style={{ flexDirection: "column", display: "flex" }}>
            <Link to={"/products/" + rec.id}>
              {"รหัสสินค้า : " + rec.product_code}
            </Link>
            <Typography style={{ fontWeight: "bold" }}>
              ({rec.year}) {rec.brand}
            </Typography>
            <Typography style={{ color: "gray" }}>{rec.model}</Typography>
            <Typography style={{ color: "gray" }}>
              เลขเครื่อง : {rec.chaiss_no}
            </Typography>
            <Typography style={{ color: "gray" }}>
              เลขไมล์ : {currencyFormat(rec.miles)}
            </Typography>
            <Typography style={{ fontWeight: "bold" }}>
              ราคาเปิดประมูล : {currencyFormat(rec.price)}
            </Typography>
          </div>
        );
      },
    },
    {
      key: 3,
      title: "ยอดประมูล",
      render: (rec) => {
        return (
          <div style={{ flexDirection: "column", display: "flex" }}>
            {rec.auction_total !== 0 ? (
              <>
                <Typography style={{ fontWeight: "bold" }}>
                  {"ยอดประมูลรถ : " + currencyFormat(rec.auction_total)}
                </Typography>
                <Typography style={{ color: "gray" }}>
                  {"ประมูลล่าสุด : " +
                    moment(rec.auction_total_update_datetime).format("lll")}
                </Typography>
              </>
            ) : (
              <Typography style={{ fontWeight: "bold", color: "red" }}>
                ไม่มีการประมูล
              </Typography>
            )}
            <Typography style={{ color: "gray" }}>
              {"ปิดประมูล : " + moment(rec.auction_due_datetime).format("lll")}
            </Typography>
          </div>
        );
      },
    },
    {
      key: 4,
      // dataIndex: "name",
      title: "ผู้ชนะประมูล",
      render: (rec) => {
        return rec.process_by_user_id ? (
          <div
            style={{
              flexDirection: "column",
              display: "flex",
              justifyContent: "start",
            }}
          >
            <Link to={"/users/" + rec.user_id}>
              {rec.user_car_tent_name || rec.user_name}
            </Link>

            {/* <Typography>อายุ : {rec.user_age}</Typography> */}
            <Typography style={{ color: "gray" }}>
              ที่อยู่ : {rec.user_car_tent_address}
            </Typography>
            <Typography style={{ color: "gray" }}>
              โทรศัพท์ : {rec.user_phone}
            </Typography>
            <Link
              style={{ marginTop: 16 }}
              onClick={() => fetchAuctionUserList(rec.id)}
            >
              ดูผู้ร่วมประมูลทั้งหมด
            </Link>
          </div>
        ) : (
          <Typography style={{ fontWeight: "bold", color: "red" }}>
            ไม่พบข้อมูลผู้ประมูล
          </Typography>
        );
      },
    },
    {
      key: 5,
      title: "สถานะ",
      render: (rec) => {
        let color;
        switch (rec.status_type_id) {
          case 1:
            color = "success";
            break;
          case 2:
            color = "processing";
            break;
          case 3:
            color = "error";
            break;
          default:
            break;
        }
        return (
          <div>
            <Tag color={color}>{rec.status}</Tag>
          </div>
        );
      },
    },
    {
      key: 6,
      title: "ตัวเลือก",
      render: function (rec) {
        return (
          <Space direction="vertical" align="center">
            <Button onClick={() => handleClickEditStatus(rec)} type="primary">
              แก้ไขสถานะสินค้า
            </Button>

            <Button onClick={() => handleClickPrintOfferPrice(rec)}>
              พิมพ์ใบเสนอราคา
            </Button>
          </Space>
        );
      },
    },
  ];

  const handleClickPrintOfferPrice = async (rec) => {
    console.log(rec);
    const docDefinition = await offerPricePDF({ rec });
    pdfMake.createPdf(docDefinition).open();
    // ReactPDF.renderToStream(<MyDocument />);
  };

  const fetchAuctionUserList = async (id) => {
    setLoading(true);
    await carApi
      .get(`/salecar/admin/auction-log/product/${id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        // console.log(response.data);
        setAuctionUserList(response.data);
        setOpenAuctionListModal(true);
        setLoading(false);
      })
      .catch((err) => {
        setLoading(false);
        dispatch(addToken({}));
        navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "กรุณาเข้าสู่ระบบ",
          centered: true,
        });
      });
  };

  useEffect(() => {
    fetchAllProduct();
  }, []);

  const fetchAllProduct = async () => {
    setLoading(true);
    await carApi
      .get("/salecar/admin/auctions-completed", {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        const data = res.data;
        // console.log("Products", data);
        setData(data);
        setLoading(false);
      })
      .catch((err) => {
        setLoading(false);
        dispatch(addToken({}));
        navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "กรุณาเข้าสู่ระบบ",
          centered: true,
        });
      });
  };

  const updateProductStatus = async (data) => {
    setLoading(true);
    await carApi
      .put("/salecar/admin/products/" + data.id + "/status", data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        if (response.status === 200) {
          Modal.success({ content: "อัพเดพข้อมูลแล้ว", centered: true });
          fetchAllProduct();
        } else {
          setLoading(false);
          Modal.error({
            title: "ผิดพลาด",
            content: "อัพเดตไม่สำเร็จ กรุณาตรวจสอบข้อมูล",
            centered: true,
          });
        }
        setLoading(false);
      })
      .catch((err) => {
        setLoading(false);
        dispatch(addToken({}));
        navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "กรุณาเข้าสู่ระบบ",
          centered: true,
        });
      });
  };

  const handleClickEditStatus = (data) => {
    console.log("EditData", data);
    setDataEdit(data);
    setOpenProductStatusModal(true);
  };

  const handleSubmit = (data) => {
    updateProductStatus(data);
  };

  if (loading) {
    return <Loading />;
  }

  return (
    <>
      <h3>รายการปิดประมูล</h3>
      <Table dataSource={data} columns={columns} />;
      <AuctionUserListModal
        open={openAuctionListModal}
        data={auctionUserList}
        // onSubmit={updateAuctionData}
        onClose={setOpenAuctionListModal}
      />
      <EditProductStatus
        open={openProductStatusModal}
        data={dataEdit}
        onSubmit={handleSubmit}
        onClose={setOpenProductStatusModal}
      />
    </>
    // <PDFViewer>
    //   <MyDocument />
    // </PDFViewer>
  );
}
