import { Button, Image, Modal, Typography, Input, Select, Space } from "antd";
import { currencyFormat } from "components/utils/Utils";
import React, { useEffect, useState } from "react";
import { useSelector } from "react-redux";

export default function BookingCarModal({
  open,
  data,
  users,
  onSubmit,
  onClose,
}) {
  const user = useSelector((state) => state.token);
  // console.log(user);
  const [product, setProduct] = useState({});
  const [loading, setLoading] = useState(false);
  const [disableSubmit, setDisableSubmit] = useState(false);
  const [price, setPrice] = useState(0);
  const [nextPrice, setNextPrice] = useState(0);

  useEffect(() => {
    setLoading(false);
    console.log(data.price);
    const price = data.auction_total === null ? data.price : data.auction_total;
    const nextPrice = price + data.auction_bitrate;
    console.log(price, nextPrice);

    setProduct({
      ...data,
      auction_total: price + data.auction_bitrate,
      process_by_user_id: user.id,
    });
    setPrice(price);
    setNextPrice(nextPrice);
    return () => {
      setProduct({});
    };
  }, [data]);

  // useEffect(() => {
  //   console.log("Product", product);
  // }, [product]);

  //   useEffect(() => {}, [price]);
  const handleSubmit = () => {
    if (product.auction_total === 0) {
    }
    // setLoading(true);
    onSubmit(product);
    onClose(false);
    // console.log("Submit");
  };

  const handleCancel = () => {
    onClose(false);
  };

  const handleChange = (e) => {
    const value = parseInt(e.target.value);

    // auctionSumBitrate = product.auction_total + product.auction_bitrate;
    if (value >= nextPrice) {
      setProduct({
        ...product,
        auction_total: value,
      });
      setDisableSubmit(false);
    } else setDisableSubmit(true);
  };

  const handleChangeSelect = (e) => {
    console.log(e);
    setProduct({
      ...product,
      // auction_total: value,
      process_by_user_id: e,
    });
  };

  return (
    <Modal
      title={"รหัสสินค้า " + product.product_code}
      open={open}
      closeIcon={false}
      footer={[
        <Button key="back" onClick={handleCancel}>
          ยกเลิก
        </Button>,
        <Button
          disabled={disableSubmit}
          key="submit"
          type="primary"
          loading={loading}
          onClick={handleSubmit}
        >
          ประมูล
        </Button>,
      ]}
    >
      <div style={{ flexDirection: "column", display: "flex" }}>
        <div>
          <Image
            // preview={false}
            //   width={isMediumUp ? 700 : 350}
            src={product.image_path}
          />
        </div>
      </div>
      <div>
        <Typography style={{ fontWeight: "bold" }}>
          {product.year} {product.brand} {product.model}
        </Typography>
        <Typography>{product.sub_model}</Typography>
        <p style={{ fontWeight: "bold", color: "red" }}>
          ราคาล่าสุด {currencyFormat(price)}
        </p>
        <p style={{ color: "blue" }}>
          ใส่ราคา บิตขั้นต่ำ + {currencyFormat(nextPrice)} บาท
          เพิ่มจากราคาล่าสุด{" "}
        </p>
        <Space direction="vertical" style={{ width: "100%" }}>
          <Input
            type="number"
            placeholder="ราคา"
            defaultValue={nextPrice}
            onChange={handleChange}
          ></Input>
          {user.role === "admin" && (
            <Select
              style={{ width: "100%" }}
              onChange={handleChangeSelect}
              // size="small"
              placeholder="เลือกผู้ประมูล"
              options={users.map((item) => ({
                value: item.id,
                label:
                  item.firstname +
                  " " +
                  item.lastname +
                  " ( " +
                  item.nickname +
                  " )",
              }))}
            />
          )}
        </Space>
      </div>
    </Modal>
  );
}
